import React from 'react';

import BGU from '@components/BGU';
import { round } from '@helpers/mathHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohLoader from '@ui-kit/Loader';

import { getRecipeByIdAsync } from '../../@services/recipes.service';
import { IFullRecipe } from '../../@types/recipes.types';
import RecipeCookingInfo from '../RecipeCookingInfo';
interface IRecipeOneProps {
  onClose?: () => void;
  recipeData?: IFullRecipe;
  id_recipe: number;
}

const RecipeOne: React.FC<IRecipeOneProps> = ({ id_recipe, recipeData }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [recipe, setRecipe] = React.useState<IFullRecipe | null>(recipeData ?? null);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const rd = recipeData || (await getRecipeByIdAsync(id_recipe));
        setRecipe(rd);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [recipeData, id_recipe]);

  if (isLoading) {
    return (
      <div className="m-6 p-6 text-center">
        <PohLoader />
      </div>
    );
  }

  if (!recipe || err) {
    return (
      <div className="m-6 p-6 text-center">
        <PohAlert variant={AlertVariant.Danger}>{err?.message ?? 'Has no recipe data'}</PohAlert>
      </div>
    );
  }

  return (
    <div>
      <PohRow>
        <PohCol sm={10}>
          <h3>{recipe.name}</h3>
          <div className="mt-n1 d-flex">
            <small className="text-secondary ">{recipe.promo}</small>
          </div>
          <p>
            <small
              style={{ wordWrap: 'break-word' }}
              dangerouslySetInnerHTML={{
                __html: recipe.text ?? '',
              }}
            />
          </p>
          <p className="d-flex flex-wrap align-items-center">
            <BGU
              portion={round(recipe.amount, 0)}
              energy={round(recipe.energy, 0)}
              protein={round(recipe.protein, 0)}
              fat={round(recipe.fat, 0)}
              carbohydrates={round(recipe.carbs, 0)}
              unit="в порции"
              className=""
            />
            <RecipeCookingInfo
              className="ms-auto"
              style={{ gap: 6 }}
              members_count={1}
              cooking_time={recipe.cooking_time}
              water_count={recipe.water_count}
              gas_count={recipe.gas_count}
            />
          </p>
        </PohCol>
        <PohCol sm={2} className="text-end">
          <PohAva
            src={recipe.photo}
            alt={recipe.name}
            colorize
            style={{
              width: '100%',
              aspectRatio: 1,
              height: 'auto',
              maxWidth: 80,
            }}
          />
        </PohCol>
      </PohRow>

      <table className="table table-sm table-striped">
        <thead>
          <tr>
            <th>Продукт</th>
            <th className="text-end">гр.</th>
            <th className="text-end">ККал</th>
            <th className="text-end">Б</th>
            <th className="text-end">Ж</th>
            <th className="text-end">У</th>
          </tr>
        </thead>
        <tbody>
          {recipe.products.map((p) => {
            return (
              <tr key={p.id}>
                <td className="text-truncate" style={{ maxWidth: 80 }} title={p.name}>
                  <a href={`/products/${p.id_product}`} target="_blank" rel="noreferrer">
                    {p.name}
                  </a>
                </td>
                <th className="text-end">{round(p.amount, 0)}</th>
                <td className="text-end">{round(p.energy, 0)}</td>
                <td className="text-end">{round(p.protein, 0)}</td>
                <td className="text-end">{round(p.fat, 0)}</td>
                <td className="text-end">{round(p.carbs, 0)}</td>
              </tr>
            );
          })}
        </tbody>
        <tfoot>
          <tr>
            <th className="text-end">Итого (порц.):</th>
            <th className="text-end">{round(recipe.amount, 0)}</th>
            <th className="text-end">{round(recipe.energy, 0)}</th>
            <th className="text-end">{round(recipe.protein, 0)}</th>
            <th className="text-end">{round(recipe.fat, 0)}</th>
            <th className="text-end">{round(recipe.carbs, 0)}</th>
          </tr>
        </tfoot>
      </table>
    </div>
  );
};

export default RecipeOne;
